import{_ as s,C as i,o as t,c as n,a3 as a,b as d,w as r,a as l,E as c,a4 as h}from"./chunks/framework.DhF4LrUq.js";const w=JSON.parse('{"title":"Approvals and quality gates","description":"Approval workflows and quality gates - the two engines that stand between a ready release and your testers.","frontmatter":{"description":"Approval workflows and quality gates - the two engines that stand between a ready release and your testers."},"headers":[],"relativePath":"concepts/approvals-gates.md","filePath":"concepts/approvals-gates.md"}'),p={name:"concepts/approvals-gates.md"};function g(u,e,f,m,A,b){const o=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="approvals-and-quality-gates" tabindex="-1">Approvals and quality gates <a class="header-anchor" href="#approvals-and-quality-gates" aria-label="Permalink to &quot;Approvals and quality gates&quot;">​</a></h1><p>Two engines stand between a ready release and your testers: approval workflows decide that the right people have signed off, and quality gates decide that the right facts have been recorded. They are configurable data, not code — an organization that configures neither keeps an ungated pipeline; an organization that configures both gets a chain of evidence no one has to remember to collect.</p><h2 id="approval-workflows" tabindex="-1">Approval workflows <a class="header-anchor" href="#approval-workflows" aria-label="Permalink to &quot;Approval workflows&quot;">​</a></h2><p>An approval workflow is an ordered chain of groups of steps. Each step demands a signature from one of the five approval roles — <code>QA_ENGINEER</code>, <code>SECURITY_REVIEWER</code>, <code>COMPLIANCE_REVIEWER</code>, <code>APP_OWNER</code> (the product step), or <code>RELEASE_MANAGER</code> (the classic final sign-off). Groups run sequentially; within a group:</p><ul><li><strong>ALL</strong> (the parallel mode) — every step in the group must approve. All pending siblings are decidable at once.</li><li><strong>ANY</strong> (the or-mode) — the first approval satisfies the group; the remaining steps are recorded as skipped, with which signature satisfied them.</li><li><strong>Conditional steps</strong> — a step can carry a trigger, evaluated when the round starts: <code>ENVIRONMENT_EQUALS</code> (for example, only demand compliance when the release targets production) or <code>FEATURE_FLAG_CONTAINS</code>. An unmet condition skips the step — never silently; the rationale is recorded.</li></ul><p>A rejection anywhere rejects the round — a no is never outvoted.</p>',6)),(t(),d(h,null,{default:r(()=>[c(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20CROSS%5B%22Release%20crosses%3Cbr%2F%3EREADY%20to%20APPROVAL_PENDING%22%5D%0A%20%20%20%20RESOLVE%5B%22Resolve%20the%20workflow%3A%3Cbr%2F%3Eenvironment%20policy%2C%20else%20ring%20chain%22%5D%0A%20%20%20%20ROUND%5B%22Round%20instantiated%3A%3Cbr%2F%3Eone%20step%20per%20applicable%20signature%2C%3Cbr%2F%3Eeach%20requester%20notified%22%5D%0A%20%20%20%20GROUPS%5B%22Groups%20run%20in%20order%3Cbr%2F%3Egroup%20N%2B1%20waits%20for%20group%20N%22%5D%0A%20%20%20%20ALL%5B%22ALL%20group%3A%3Cbr%2F%3Eevery%20step%20approves%22%5D%0A%20%20%20%20ANY%5B%22ANY%20group%3A%3Cbr%2F%3Efirst%20approval%20wins%2C%3Cbr%2F%3Esiblings%20recorded%20skipped%22%5D%0A%20%20%20%20COND%5B%22Conditional%20step%3A%3Cbr%2F%3Etrigger%20unmet%20%3D%20skipped%3Cbr%2F%3Ewith%20recorded%20rationale%22%5D%0A%20%20%20%20SAT%5B%22Round%20satisfied%22%5D%0A%20%20%20%20APP%5B%22Crossing%20to%20APPROVED%20fires%3Cbr%2F%3Echain%20frozen%20into%20the%20manifest%22%5D%0A%20%20%20%20REJ%5B%22A%20step%20REJECTS%3Cbr%2F%3E(reason%20mandatory)%22%5D%0A%20%20%20%20HOLD%5B%22Release%20stays%20APPROVAL_PENDING%3Cbr%2F%3Erejection%20recorded%22%5D%0A%20%20%20%20REWORK%5B%22A%20NEW%20round%20of%20the%20same%3Cbr%2F%3Efrozen%20definition%3Cbr%2F%3E(restart%20action)%22%5D%0A%0A%20%20%20%20CROSS%20--%3E%20RESOLVE%20--%3E%20ROUND%20--%3E%20GROUPS%0A%20%20%20%20GROUPS%20--%3E%20ALL%0A%20%20%20%20GROUPS%20--%3E%20ANY%0A%20%20%20%20GROUPS%20--%3E%20COND%0A%20%20%20%20ALL%20--%3E%7C%22last%20group%20satisfied%22%7C%20SAT%0A%20%20%20%20ANY%20--%3E%7C%22first%20signature%22%7C%20SAT%0A%20%20%20%20COND%20--%3E%7C%22skipped%20counts%20for%20nothing%22%7C%20SAT%0A%20%20%20%20SAT%20--%3E%20APP%0A%20%20%20%20ALL%20--%3E%7C%22a%20rejection%22%7C%20REJ%0A%20%20%20%20ANY%20--%3E%7C%22a%20rejection%22%7C%20REJ%0A%20%20%20%20REJ%20--%3E%20HOLD%20--%3E%20REWORK%20--%3E%20GROUPS%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The details that matter in practice:</p><ul><li><strong>Signatures are facts.</strong> Approver and role are recorded at decision time; roles change later, the record does not.</li><li><strong>The release&#39;s creator signs nothing</strong> — self-approval is refused.</li><li><strong>Rejection is terminal for the round.</strong> The documented rework path is a new round of the same frozen definition — never an un-reject.</li><li><strong>Rounds are per definition, and the chain is what the manifest freezes</strong>: the signed steps, in chain order.</li><li><strong>A named policy that fails to resolve fails closed</strong>: the crossing refuses rather than silently running a weaker chain.</li></ul><h2 id="quality-gates" tabindex="-1">Quality gates <a class="header-anchor" href="#quality-gates" aria-label="Permalink to &quot;Quality gates&quot;">​</a></h2><p>Gates are evaluated facts, not workflows: external systems (usually your CI) submit results with evidence, the platform records them, and the release&#39;s crossing consults them. The built-in catalog:</p><table tabindex="0"><thead><tr><th>Gate</th><th>Kind</th><th>Semantics</th></tr></thead><tbody><tr><td><code>unit-tests</code>, <code>integration-tests</code>, <code>sast</code>, <code>dependency-scan</code>, <code>mobile-security-scan</code></td><td>Pass/fail</td><td>Externally reported binary outcome, with a mandatory evidence URL</td></tr><tr><td><code>coverage-threshold</code></td><td>Minimum</td><td>A percentage the definition pins (for example, 80)</td></tr><tr><td><code>crash-free-threshold</code></td><td>Minimum</td><td>Metric-backed: crash-free session rate</td></tr><tr><td><code>open-critical-bugs</code></td><td>Maximum</td><td>Metric-backed: a ceiling, typically 0, fed by feedback triage</td></tr></tbody></table><p>How they bind: gate definitions are organization-grain, with an optional ring attachment — a ring-attached definition overrides the organization-wide one for that ring (per-ring gates, PRD&#39;s rule).</p><p>How they decide:</p><ul><li><strong>Blocking.</strong> While any required gate of the release&#39;s ring is pending, failed, or without data, the <code>VALIDATING</code> to <code>READY</code> crossing refuses — and a ring promotion consults the same evaluation for the target ring.</li><li><strong>NO_DATA is not zero and not a pass.</strong> A metric-backed gate with no data yet blocks, distinctly from a failure — no data yet is not a bad result, but it holds all the same.</li><li><strong>Results are latest-wins with full history.</strong> Every submission is appended; the current state mirrors the newest result.</li><li><strong>Evidence is mandatory.</strong> Every externally reported result carries an http(s) URL a human can follow — the report link, not a claim.</li><li><strong>Overrides are the governed exception.</strong> A failed or dataless gate can be overridden exactly once, with a mandatory reason, by the roles that hold the override authority. The row keeps reporting the underlying state; the override governs whether it still blocks, and the act is audited.</li><li><strong>Metric-backed gates refuse manual submission</strong> — analytics and feedback own their values.</li></ul><h2 id="how-the-two-interlock-with-feedback" tabindex="-1">How the two interlock with feedback <a class="header-anchor" href="#how-the-two-interlock-with-feedback" aria-label="Permalink to &quot;How the two interlock with feedback&quot;">​</a></h2><p>The <code>open-critical-bugs</code> gate reads live feedback triage: unresolved critical reports block promotion into a ring that demands zero. Resolve the report and the next attempt re-evaluates and passes. That closed loop — report, triage, metric, gate, promotion — is covered in <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback and analytics</a>.</p><h2 id="release-policies-the-standing-rules" tabindex="-1">Release policies (the standing rules) <a class="header-anchor" href="#release-policies-the-standing-rules" aria-label="Permalink to &quot;Release policies (the standing rules)&quot;">​</a></h2><p>Beside gates, an organization authors declarative IF/THEN rules that every promotion evaluates: metrics and gate states in the condition, <code>BLOCK</code> / <code>HOLD_FOR_REVIEW</code> / <code>ALLOW</code> in the action, scoped to the organization, an application, a ring, or the targeted environment. A fired <code>HOLD_FOR_REVIEW</code> rule parks the hop until a privileged acknowledge records the decision — with a reason — and that decision stands for later hops into the same ring. See <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a>.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/release-lifecycle">Release lifecycle</a> — the crossings these engines guard</li><li>Developer detail: the approval-workflow, gate, and policy sections of the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/releases.md" target="_blank" rel="noreferrer">releases</a> module doc, and the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/ci.md" target="_blank" rel="noreferrer">CI integration</a> guide for submitting gate results from pipelines.</li></ul>',14))])}const v=s(p,[["render",g]]);export{w as __pageData,v as default};
